```javascript
const state = {
    currentMode: 'kutatas',
    currentJobId: null,
    uploadedFiles: [],
    jobs: [],
    ws: null,
    reasoningHistory: [],
    taskStates: [],
    updateInterval: null,
    realtimeInterval: null
};

const API_BASE = window.location.origin;

document.addEventListener('DOMContentLoaded', () => {
    initializeApp();
});

async function initializeApp() {
    setupEventListeners();
    await loadJobs();
    updateStats();
    state.updateInterval = setInterval(updateStats, 5000);
}

function setupEventListeners() {
    document.querySelectorAll('.mode-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.mode-btn').forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            state.currentMode = btn.dataset.mode;
        });
    });

    const fileUploadArea = document.getElementById('fileUploadArea');
    const fileInput = document.getElementById('fileInput');

    fileUploadArea.addEventListener('click', () => fileInput.click());

    fileUploadArea.addEventListener('dragover', (e) => {
        e.preventDefault();
        fileUploadArea.classList.add('dragover');
    });

    fileUploadArea.addEventListener('dragleave', () => {
        fileUploadArea.classList.remove('dragover');
    });

    fileUploadArea.addEventListener('drop', async (e) => {
        e.preventDefault();
        fileUploadArea.classList.remove('dragover');
        const files = Array.from(e.dataTransfer.files);
        await handleFiles(files);
    });

    fileInput.addEventListener('change', async (e) => {
        const files = Array.from(e.target.files);
        await handleFiles(files);
    });

    document.getElementById('startResearchBtn').addEventListener('click', startResearch);
    document.getElementById('clearBtn').addEventListener('click', clearForm);
    document.getElementById('downloadPdfBtn')?.addEventListener('click', downloadPdf);

    document.getElementById('queryInput').addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && e.ctrlKey) {
            startResearch();
        }
    });
}

async function handleFiles(files) {
    for (const file of files) {
        const formData = new FormData();
        formData.append('file', file);

        try {
            const response = await fetch(`${API_BASE}/upload`, {
                method: 'POST',
                body: formData
            });

            if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

            const data = await response.json();
            state.uploadedFiles.push({
                id: data.file_id,
                name: data.filename,
                size: data.size,
                path: data.path
            });

            renderUploadedFiles();
        } catch (error) {
            console.error('Upload error:', error);
            alert(`Hiba a fájl feltöltésekor: ${error.message}`);
        }
    }
}

function renderUploadedFiles() {
    const container = document.getElementById('uploadedFiles');
    container.innerHTML = state.uploadedFiles.map(file => `<div class="file-chip"><span>📎 ${escapeHtml(file.name)}</span><span class="file-chip-remove" onclick="removeFile('${file.id}')">×</span></div>`).join('');
}

function removeFile(fileId) {
    state.uploadedFiles = state.uploadedFiles.filter(f => f.id !== fileId);
    renderUploadedFiles();
}

async function startResearch() {
    const query = document.getElementById('queryInput').value.trim();
    if (!query) {
        alert('Kérlek add meg a kutatási kérdést!');
        return;
    }

    const startDate = document.getElementById('startDate').value;
    const endDate = document.getElementById('endDate').value;
    const category = document.getElementById('category').value;
    const excludeDomains = document.getElementById('excludeDomains').value
        .split(',')
        .map(d => d.trim())
        .filter(d => d.length > 0);

    const requestBody = {
        mode: state.currentMode,
        prompt: query,
        time_limit_minutes: parseInt(document.getElementById('timeLimit').value),
        max_sources: parseInt(document.getElementById('maxSources').value),
        attached_files: state.uploadedFiles.map(f => f.id)
    };

    if (startDate) requestBody.start_published_date = startDate;
    if (endDate) requestBody.end_published_date = endDate;
    if (category) requestBody.search_category = category;
    if (excludeDomains.length > 0) requestBody.exclude_domains = excludeDomains;

    try {
        const response = await fetch(`${API_BASE}/query`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(requestBody)
        });

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();
        state.currentJobId = data.job_id;

        document.getElementById('resultsPanel').style.display = 'block';
        resetResultsPanel();

        connectWebSocket(data.job_id);

        await loadJobs();

        document.getElementById('resultsPanel').scrollIntoView({ behavior: 'smooth' });

    } catch (error) {
        console.error('Research error:', error);
        alert(`Hiba a kutatás indításakor: ${error.message}`);
    }
}

function resetResultsPanel() {
    document.getElementById('statusBadge').className = 'status-badge status-running';
    document.getElementById('statusBadge').textContent = '▶️ Futás alatt';
    document.getElementById('progressFill').style.width = '0%';
    document.getElementById('progressText').textContent = '0%';
    document.getElementById('currentStep').textContent = 'Inicializálás...';
    document.getElementById('metricsGrid').innerHTML = '';
    document.getElementById('reportSection').style.display = 'none';
    document.getElementById('sourcesSection').style.display = 'none';
}

function connectWebSocket(jobId) {
    const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';

    if (state.ws) {
        state.ws.close();
    }

    state.ws = new WebSocket(`${wsProtocol}//${window.location.host}/ws/${jobId}`);

    state.ws.onmessage = async (event) => {
        try {
            const data = JSON.parse(event.data);
            updateProgress(data);

            if (data.status === 'completed') {
                state.ws.close();
                await loadReport(jobId);
                await loadReasoning(jobId);
                await loadTaskStates(jobId);
            } else if (data.status === 'failed') {
                state.ws.close();
                showError(data.error);
            }
        } catch (error) {
            console.error('WebSocket message parse error:', error);
        }
    };

    state.ws.onerror = (error) => {
        console.error('WebSocket error:', error);
    };

    state.ws.onclose = () => {
        state.ws = null;
    };

    startRealtimeUpdates(jobId);
}

function updateProgress(data) {
    const progress = Math.round((data.progress || 0) * 100);
    document.getElementById('progressFill').style.width = `${progress}%`;
    document.getElementById('progressText').textContent = `${progress}%`;
    document.getElementById('currentStep').textContent = escapeHtml(data.current_step || 'Feldolgozás...');

    if (data.status) {
        const badge = document.getElementById('statusBadge');
        badge.className = `status-badge status-${data.status}`;
        badge.textContent = getStatusText(data.status);
    }
}

function getStatusText(status) {
    const texts = {
        'pending': '⏳ Várakozás',
        'running': '▶️ Futás alatt',
        'completed': '✅ Befejezve',
        'failed': '❌ Hiba'
    };
    return texts[status] || status;
}

function showError(error) {
    const badge = document.getElementById('statusBadge');
    badge.className = 'status-badge status-failed';
    badge.textContent = '❌ Hiba';
    document.getElementById('currentStep').innerHTML = `<span style="color: var(--danger);">${escapeHtml(error || 'Ismeretlen hiba történt')}</span>`;
}

async function loadReport(jobId) {
    try {
        const response = await fetch(`${API_BASE}/report/${jobId}`);

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();

        const metricsGrid = document.getElementById('metricsGrid');
        metricsGrid.innerHTML = `
            <div class="metric-card">
                <div class="metric-value">${data.sources_count || 0}</div>
                <div class="metric-label">Források</div>
            </div>
            <div class="metric-card">
                <div class="metric-value">${Math.round((data.knowledge_metrics?.source_diversity || 0) * 100)}%</div>
                <div class="metric-label">Diverzitás</div>
            </div>
            <div class="metric-card">
                <div class="metric-value">${data.knowledge_metrics?.high_reliability_sources || 0}</div>
                <div class="metric-label">Megbízható</div>
            </div>
            <div class="metric-card">
                <div class="metric-value">${data.reasoning_metrics?.total_reasoning_cycles || 0}</div>
                <div class="metric-label">Gondolkodási ciklusok</div>
            </div>
            <div class="metric-card">
                <div class="metric-value">${data.execution_stats?.total_tasks || 0}</div>
                <div class="metric-label">Feladatok</div>
            </div>
            <div class="metric-card">
                <div class="metric-value">${Math.round(data.execution_stats?.avg_task_duration || 0)}s</div>
                <div class="metric-label">Átl. idő</div>
            </div>
        `;

        document.getElementById('reportSection').style.display = 'block';
        document.getElementById('reportContent').innerHTML = formatMarkdown(data.report);

        await loadSources(jobId);

    } catch (error) {
        console.error('Report loading error:', error);
    }
}

async function loadSources(jobId) {
    try {
        const response = await fetch(`${API_BASE}/sources/${jobId}`);

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();

        const sourcesSection = document.getElementById('sourcesSection');
        sourcesSection.style.display = 'block';
        sourcesSection.innerHTML = `
            <div class="panel-title">🔗 Források (${data.sources.length})</div>
            ${data.sources.slice(0, 20).map(source => `
                <div class="source-item">
                    <div class="source-title">${escapeHtml(source.title || 'Untitled')}</div>

                        ${escapeHtml(source.url)}

                    <div class="source-meta">
                        ${source.score ? `Score: ${source.score.toFixed(2)}` : ''} 
                        ${source.published_date ? `| ${new Date(source.published_date).toLocaleDateString()}` : ''}
                    </div>
                </div>
            `).join('')}
            ${data.sources.length > 20 ? `<div style="text-align: center; margin-top: 12px; color: var(--text-muted);">És még ${data.sources.length - 20} forrás...</div>` : ''}
        `;
    } catch (error) {
        console.error('Sources loading error:', error);
    }
}

async function loadReasoning(jobId) {
    try {
        const response = await fetch(`${API_BASE}/reasoning/${jobId}`);

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();
        state.reasoningHistory = data.reasoning_history || [];
        renderReasoning();
    } catch (error) {
        console.error('Reasoning loading error:', error);
    }
}

function renderReasoning() {
    const container = document.getElementById('reasoningLog');
    if (state.reasoningHistory.length === 0) {
        container.innerHTML = '<div class="empty-state" style="padding: 20px;"><div style="font-size: 1.5rem;">🤔</div><div style="font-size: 0.8rem;">Nincs gondolkodási folyamat</div></div>';
        return;
    }

    container.innerHTML = state.reasoningHistory.slice(-10).reverse().map(item => `
        <div class="reasoning-item">
            <div class="reasoning-agent">${escapeHtml(item.agent_level?.toUpperCase() || 'SYSTEM')}</div>
            <div class="reasoning-text">${escapeHtml(item.reasoning_text || '')}</div>
        </div>
    `).join('');
}

async function loadTaskStates(jobId) {
    try {
        const response = await fetch(`${API_BASE}/task-states/${jobId}`);

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();
        state.taskStates = Object.values(data.task_states || {});
        renderTasks();
    } catch (error) {
        console.error('Task states loading error:', error);
    }
}

function renderTasks() {
    const container = document.getElementById('taskList');
    if (state.taskStates.length === 0) {
        container.innerHTML = '<div class="empty-state" style="padding: 20px;"><div style="font-size: 1.5rem;">✓</div><div style="font-size: 0.8rem;">Nincs feladat</div></div>';
        return;
    }

    container.innerHTML = state.taskStates.map(task => `
        <div class="task-item">
            <div class="task-header">
                <div class="task-name">${escapeHtml(task.task_name || task.task_id || 'Task')}</div>
                <div class="task-status ${task.status}">${escapeHtml(task.status || 'unknown')}</div>
            </div>
            ${task.result ? `<div style="font-size: 0.75rem; color: var(--text-muted); margin-top: 4px;">${escapeHtml(task.result)}</div>` : ''}
        </div>
    `).join('');
}

function startRealtimeUpdates(jobId) {
    if (state.realtimeInterval) {
        clearInterval(state.realtimeInterval);
    }

    state.realtimeInterval = setInterval(async () => {
        if (state.currentJobId !== jobId || !state.ws) {
            clearInterval(state.realtimeInterval);
            state.realtimeInterval = null;
            return;
        }

        try {
            await loadReasoning(jobId);
            await loadTaskStates(jobId);
        } catch (error) {
            console.error('Realtime update error:', error);
        }
    }, 2000);
}

async function loadJobs() {
    try {
        const response = await fetch(`${API_BASE}/jobs`);

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();
        state.jobs = data;
        renderJobs();
    } catch (error) {
        console.error('Jobs loading error:', error);
    }
}

function renderJobs() {
    const container = document.getElementById('jobsList');
    if (state.jobs.length === 0) {
        container.innerHTML = '<div class="empty-state"><div style="font-size: 2rem;">📭</div><div style="font-size: 0.85rem;">Még nincs kutatás</div></div>';
        return;
    }

    container.innerHTML = state.jobs.slice().reverse().map(job => `
        <div class="job-item ${job.job_id === state.currentJobId ? 'active' : ''}" onclick="selectJob('${job.job_id}')">
            <div class="job-title">${escapeHtml(job.prompt)}</div>
            <div class="job-meta">
                <span>${escapeHtml(job.status)}</span>
                <span>${Math.round(job.progress * 100)}%</span>
            </div>
        </div>
    `).join('');
}

async function selectJob(jobId) {
    state.currentJobId = jobId;
    document.getElementById('resultsPanel').style.display = 'block';

    try {
        const response = await fetch(`${API_BASE}/status/${jobId}`);

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();

        updateProgress(data);

        if (data.status === 'completed') {
            await loadReport(jobId);
            await loadReasoning(jobId);
            await loadTaskStates(jobId);
        } else if (data.status === 'running') {
            connectWebSocket(jobId);
        }

        renderJobs();
    } catch (error) {
        console.error('Job selection error:', error);
    }
}

function updateStats() {
    const total = state.jobs.length;
    const completed = state.jobs.filter(j => j.status === 'completed').length;
    const running = state.jobs.filter(j => j.status === 'running').length;

    document.getElementById('totalJobs').textContent = total;
    document.getElementById('completedJobs').textContent = completed;
    document.getElementById('runningJobs').textContent = running;
}

async function downloadPdf() {
    if (!state.currentJobId) return;

    try {
        const response = await fetch(`${API_BASE}/export-pdf/${state.currentJobId}`);

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `kutatasi-jelentes-${state.currentJobId}.pdf`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
    } catch (error) {
        console.error('PDF download error:', error);
        alert(`Hiba a PDF letöltésekor: ${error.message}`);
    }
}

function clearForm() {
    document.getElementById('queryInput').value = '';
    state.uploadedFiles = [];
    renderUploadedFiles();
    document.getElementById('startDate').value = '';
    document.getElementById('endDate').value = '';
    document.getElementById('category').value = '';
    document.getElementById('excludeDomains').value = '';
}

function formatMarkdown(text) {
    if (!text) return '';

    let html = escapeHtml(text);

    html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
    html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
    html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');

    html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');

    const listRegex = /^- (.+)$/gm;
    const lines = html.split('\n');
    let inList = false;
    let result = [];

    for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const isListItem = /^- /.test(line);

        if (isListItem && !inList) {
            result.push('<ul>');
            inList = true;
        } else if (!isListItem && inList) {
            result.push('</ul>');
            inList = false;
        }

        if (isListItem) {
            result.push(`<li>${line.replace(/^- /, '')}</li>`);
        } else if (line.trim() !== '') {
            result.push(line);
        }
    }

    if (inList) {
        result.push('</ul>');
    }

    html = result.join('\n');
    html = html.replace(/\n\n/g, '</p><p>');

    return '<p>' + html + '</p>';
}

function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function togglePanel(panelId) {
    const panel = document.getElementById(panelId);
    const isVisible = panel.style.display !== 'none';
    panel.style.display = isVisible ? 'none' : 'block';

    if (!isVisible && panelId === 'chartsPanel' && state.currentJobId) {
        renderCharts();
    } else if (!isVisible && panelId === 'knowledgeGraphPanel') {
        loadKnowledgeGraph();
    }
}

let graphNetwork = null;

async function loadKnowledgeGraph() {
    if (!state.currentJobId) {
        alert('Először válassz ki egy kutatást!');
        return;
    }

    try {
        const response = await fetch(`${API_BASE}/sources/${state.currentJobId}`);

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const sources = await response.json();

        const nodes = [];
        const edges = [];
        const nodeSet = new Set();

        nodes.push({
            id: 'center',
            label: 'Kutatás',
            color: '#0A84FF',
            size: 30,
            font: { color: '#ffffff' }
        });

        sources.sources.slice(0, 30).forEach((source, idx) => {
            try {
                const domain = new URL(source.url).hostname;

                if (!nodeSet.has(domain)) {
                    nodeSet.add(domain);
                    nodes.push({
                        id: domain,
                        label: domain,
                        color: '#34C759',
                        size: 20,
                        title: domain
                    });
                    edges.push({
                        from: 'center',
                        to: domain,
                        color: { color: 'rgba(52, 199, 89, 0.3)' }
                    });
                }

                const sourceId = `source-${idx}`;
                nodes.push({
                    id: sourceId,
                    label: source.title.substring(0, 30) + '...',
                    color: '#94a3b8',
                    size: 15,
                    title: source.title,
                    url: source.url
                });
                edges.push({
                    from: domain,
                    to: sourceId,
                    color: { color: 'rgba(148, 163, 184, 0.3)' }
                });
            } catch (e) {
                console.warn('Invalid URL:', source.url);
            }
        });

        const container = document.getElementById('knowledgeGraph');
        const data = { nodes, edges };
        const options = {
            nodes: {
                shape: 'dot',
                font: { color: '#f0f0f0', size: 12 }
            },
            edges: {
                width: 1,
                smooth: { type: 'continuous' }
            },
            physics: {
                stabilization: { iterations: 200 },
                barnesHut: { gravitationalConstant: -2000, springLength: 100 }
            },
            interaction: { hover: true }
        };

        if (graphNetwork) {
            graphNetwork.destroy();
        }
        graphNetwork = new vis.Network(container, data, options);

        graphNetwork.on('click', (params) => {
            if (params.nodes.length > 0) {
                const nodeId = params.nodes[0];
                const node = nodes.find(n => n.id === nodeId);
                if (node && node.url) {
                    window.open(node.url, '_blank');
                }
            }
        });

    } catch (error) {
        console.error('Knowledge graph error:', error);
        alert(`Hiba a tudásgráf betöltésekor: ${error.message}`);
    }
}

let charts = {};

function renderCharts() {
    if (!state.currentJobId) return;

    renderSourceTypesChart();
    renderTaskStatusChart();
    renderProgressTimeChart();
    renderReliabilityChart();
}

function renderSourceTypesChart() {
    const ctx = document.getElementById('sourceTypesChart');
    if (!ctx) return;

    if (charts.sourceTypes) {
        charts.sourceTypes.destroy();
    }

    const types = { pdf: 0, news: 0, research: 0, github: 0, other: 0 };

    state.jobs.forEach(job => {
        const mode = (job.mode || '').toLowerCase();
        if (mode.includes('pdf')) types.pdf++;
        else if (mode.includes('news')) types.news++;
        else if (mode.includes('research')) types.research++;
        else if (mode.includes('github')) types.github++;
        else types.other++;
    });

    charts.sourceTypes = new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: ['PDF', 'Hírek', 'Kutatás', 'GitHub', 'Egyéb'],
            datasets: [{
                data: [types.pdf, types.news, types.research, types.github, types.other],
                backgroundColor: ['#FF3B30', '#0A84FF', '#34C759', '#FF9500', '#94a3b8']
            }]
        },
        options: {
            responsive: true,
            plugins: {
                legend: { labels: { color: '#f0f0f0' } }
            }
        }
    });
}

function renderTaskStatusChart() {
    const ctx = document.getElementById('taskStatusChart');
    if (!ctx) return;

    if (charts.taskStatus) {
        charts.taskStatus.destroy();
    }

    const statuses = { completed: 0, running: 0, pending: 0, failed: 0 };
    state.taskStates.forEach(task => {
        statuses[task.status] = (statuses[task.status] || 0) + 1;
    });

    charts.taskStatus = new Chart(ctx, {
        type: 'pie',
        data: {
            labels: ['Befejezett', 'Futó', 'Várakozó', 'Sikertelen'],
            datasets: [{
                data: [statuses.completed, statuses.running, statuses.pending, statuses.failed],
                backgroundColor: ['#34C759', '#0A84FF', '#94a3b8', '#FF3B30']
            }]
        },
        options: {
            responsive: true,
            plugins: {
                legend: { labels: { color: '#f0f0f0' } }
            }
        }
    });
}

function renderProgressTimeChart() {
    const ctx = document.getElementById('progressTimeChart');
    if (!ctx) return;

    if (charts.progressTime) {
        charts.progressTime.destroy();
    }

    const data = state.jobs.slice(-10).map(job => ({
        x: job.job_id.substring(0, 6),
        y: Math.round(job.progress * 100)
    }));

    charts.progressTime = new Chart(ctx, {
        type: 'line',
        data: {
            labels: data.map(d => d.x),
            datasets: [{
                label: 'Előrehaladás %',
                data: data.map(d => d.y),
                borderColor: '#0A84FF',
                backgroundColor: 'rgba(10, 132, 255, 0.1)',
                tension: 0.4
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: { 
                    beginAtZero: true, 
                    max: 100,
                    ticks: { color: '#f0f0f0' }
                },
                x: { ticks: { color: '#f0f0f0' } }
            },
            plugins: {
                legend: { labels: { color: '#f0f0f0' } }
            }
        }
    });
}

function renderReliabilityChart() {
    const ctx = document.getElementById('reliabilityChart');
    if (!ctx) return;

    if (charts.reliability) {
        charts.reliability.destroy();
    }

    const data = [
        Math.floor(Math.random() * 30 + 20),
        Math.floor(Math.random() * 40 + 30),
