async function runExaKeywordSearch() {
    const query = document.getElementById('exaQuery').value.trim();
    if (!query) {
        alert('Add meg a keresési kérdést!');
        return;
    }

    try {
        const response = await fetch(`${API_BASE}/exa/keyword-search`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                query: query,
                num_results: 10
            })
        });

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();
        displayExaResults(data);
    } catch (error) {
        console.error('Exa keyword search error:', error);
        alert(`Hiba a keresés során: ${error.message}`);
    }
}

