function displayExaResults(data) {
    const container = document.getElementById('exaResults');
    const results = data.results || [];

    if (results.length === 0) {
        container.innerHTML = '<div style="color: var(--text-muted);">Nincs találat</div>';
        return;
    }

    container.innerHTML = `
        <div class="sidebar-title" style="margin-bottom: 8px;">Találatok (${results.length})</div>
        ${results.map(result => `
            <div class="source-item" style="margin-bottom: 8px;">
                <div class="source-title">${escapeHtml(result.title || 'Untitled')}</div>

                    ${escapeHtml(result.url)}

                ${result.score ? `<div class="source-meta">Score: ${result.score.toFixed(2)}</div>` : ''}
            </div>
        `).join('')}
    `;
}

async function processUploadedDocument(fileId) {
    try {
        const response = await fetch(`${API_BASE}/process-document/${fileId}`, {
            method: 'POST'
        });

        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);

        const data = await response.json();

        const container = document.getElementById('processedDocuments');
        container.innerHTML += `
            <div class="source-item" style="margin-bottom: 8px;">
                <div class="source-title">Feldolgozott: ${escapeHtml(data.method || 'unknown')}</div>
                <div class="source-meta">
                    Szavak: ${data.word_count || 0} | 
                    ${data.confidence ? `Bizalom: ${data.confidence.toFixed(0)}%` : ''}
                    ${data.page_count ? `| Oldalak: ${data.page_count}` : ''}
                </div>
            </div>
        `;

        return data;
    } catch (error) {
        console.error('Document processing error:', error);
        return null;
    }
}

